<div class="d-flex justify-content-between mb-3"><h4>Stock Adjustments</h4><?php if (Auth::can('inventory.stock.adjust')): ?><a class="btn btn-primary" href="<?= url('stock/adjust') ?>"><i class="bi bi-plus-lg"></i> New</a><?php endif; ?></div>
<div class="btn-group mb-3"><?php foreach (['' => 'All', 'pending' => 'Pending', 'approved' => 'Approved', 'rejected' => 'Rejected'] as $k => $l): ?><a class="btn btn-sm btn-outline-secondary <?= $st === $k ? 'active' : '' ?>" href="<?= url('stock/adjustments', $k ? ['status' => $k] : []) ?>"><?= $l ?></a><?php endforeach; ?></div>
<div class="card"><div class="table-responsive"><table class="table table-sm mb-0 align-middle small"><thead class="table-light"><tr><th>No</th><th>Date</th><th>Product</th><th>Warehouse</th><th>Type</th><th class="text-end">Qty</th><th>Reason</th><th>By</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r['adj_no']) ?></td><td><?= e(fmt_date($r['created_at'], 'd M H:i')) ?></td><td><?= link_product($r['product_id'], $r['sku'] . ' ' . $r['name']) ?></td><td><?= link_wh($r['warehouse_id'], $r['warehouse']) ?></td><td><?= e($r['type']) ?></td><td class="text-end"><?= fq($r['qty']) ?></td><td><?= e($r['reason']) ?></td><td><?= e($r['creator']) ?></td><td><?= badge($r['status']) ?></td>
<td class="text-nowrap"><?php if ($r['status'] === 'pending' && Auth::can('inventory.stock.approve')): foreach (['approved' => ['success', 'check-lg'], 'rejected' => ['danger', 'x-lg']] as $d => [$c, $i]): ?><form method="post" action="<?= url('stock/decide') ?>" class="d-inline"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="decision" value="<?= $d ?>"><button class="btn btn-sm btn-outline-<?= $c ?>"><i class="bi bi-<?= $i ?>"></i></button></form><?php endforeach; endif; ?></td></tr><?php endforeach; ?>
<?php if (!$rows): ?><tr><td colspan="10" class="text-center text-muted py-3">No adjustments.</td></tr><?php endif; ?></tbody></table></div></div>
